#include "can_v_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static ID_Range * find_min (ID_Set * set) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void can_v_id_set_sort (ID_Set * set)
{
  ID_Range * min ;

  ID_Set   * set_sorted = can_v_id_set_create () ;

  while ((min = find_min (set))!= FALSE) // check for false added to eliminate compile warning.
    {
      can_v_id_range_unlink   (min) ;

      can_v_id_set_insert_rhs (set_sorted , min) ;
    }

  can_v_id_set_append_rhs (set , set_sorted) ;

  can_v_id_set_delete     (set_sorted)       ;
}

//--------------------------------------------------------------------------//

static ID_Range * find_min (ID_Set * set)
{
  ID_Range      * min  ;
  ID_Range      * curr ;
  ID_Set_Iterator iter ;

  can_v_id_set_iterator_init (& iter , & curr , set , ITER_L2R) ;

  for (min = curr ; curr ; can_v_id_set_iterator_next (& iter , & curr))
    {
      if (curr->min < min->min)
        {
          min = curr ;
        }
    }

  return min ;
}
